questions.solution:
function labeledText(id, labelText, name) {
  return '<label for="' + id + '">' + labelText + '</label><input id="' + id + '" type="text" name="' + name + '" />';
}

function formPost(action, inner) {
  return '<form action="' + action + '" method="post">' + inner + '</form>';
}
